-- MyNclex gap-fill batch: Management of Care / delegation, supervision and care coordination
-- Batch: gapfill-20260728   Block: 530001-530999   Items: 55
-- Subject: Leadership and Management. Category: Safe and Effective Care Environment.
-- Generated 2026-07-28.

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_530001', 'MCQ', 'A registered nurse on a medical ward is planning the shift with a licensed practical nurse. Which task is appropriate for the registered nurse to delegate to the licensed practical nurse?', 'The licensed practical nurse works within a plan of care that the registered nurse has already established. Monitoring an infusion that is already running - checking the rate, the site and the volume remaining - falls inside that scope. Initiating intravenous therapy, giving an intravenous push dose and administering a blood product each demand independent assessment and carry an immediate risk, so each remains with the registered nurse.',
 '{"options": [{"id": "A", "text": "Insert a new peripheral cannula and start a prescribed infusion"}, {"id": "B", "text": "Monitor and maintain an infusion of 0.9% sodium chloride that the registered nurse has already commenced"}, {"id": "C", "text": "Administer a prescribed intravenous push dose of hydralazine"}, {"id": "D", "text": "Prime and connect the first unit of packed red cells for a client with anaemia"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Initiating intravenous therapy is outside the scope of the licensed practical nurse in most jurisdictions.", "B": "Correct. Maintaining an infusion that is already running is within the scope of the licensed practical nurse.", "C": "Incorrect. Intravenous push medication requires the registered nurse because the effect is immediate and unpredictable.", "D": "Incorrect. Administering blood products is a registered nurse responsibility; a reaction can occur within minutes of the start."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to the licensed practical nurse', 'Intravenous therapy scope',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530002', 'SATA', 'A registered nurse is allocating work on a surgical ward to a licensed practical nurse who is caring for four stable clients. Which tasks may the registered nurse delegate to the licensed practical nurse? Select all that apply.', 'Delegation to the licensed practical nurse rests on three tests: the client is stable, the plan of care already exists, and the task does not require a fresh nursing assessment. Administering oral medication, reinforcing teaching that has already been given and recording routine observations all meet those tests. Creating the plan of care, carrying out an admission assessment and adding a drug to an intravenous bag do not.',
 '{"options": [{"id": "A", "text": "Administer prescribed oral analgesia to a client whose pain the registered nurse has assessed"}, {"id": "B", "text": "Reinforce the wound care teaching that the registered nurse began yesterday"}, {"id": "C", "text": "Record the routine observations for a client on the second day after surgery"}, {"id": "D", "text": "Complete the admission assessment for a client arriving from the emergency department"}, {"id": "E", "text": "Add potassium chloride to a bag of intravenous fluid"}, {"id": "F", "text": "Develop the plan of care for a client newly diagnosed with type 2 diabetes"}]}'::jsonb,
 '{"answers": ["A", "B", "C"], "feedback": {"A": "Correct. Administering oral medication within an established plan is within the scope of the licensed practical nurse.", "B": "Correct. Reinforcing teaching already delivered by the registered nurse is permitted; the initial teaching is not.", "C": "Correct. Routine observations on a stable client may be delegated, with clear reporting parameters.", "D": "Incorrect. An admission assessment is a registered nurse responsibility and cannot be delegated.", "E": "Incorrect. Mixing or adding medication to intravenous fluid is outside the scope of the licensed practical nurse.", "F": "Incorrect. Creating the plan of care is a registered nurse responsibility."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to the licensed practical nurse', 'Scope of practice',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530003', 'MCQ', 'A licensed practical nurse tells the registered nurse, "The client in bed 6 is prescribed intravenous furosemide 40 mg now. I can give it while you finish the admission." Which response by the registered nurse is most appropriate?', 'Intravenous push medication is outside the scope of the licensed practical nurse, and supervision by a registered nurse does not extend a scope of practice. The registered nurse gives the dose personally and redirects the licensed practical nurse to a task that is within scope, which keeps the ward moving without a scope breach.',
 '{"options": [{"id": "A", "text": "\"Thank you - draw it up and I will check the dose with you before you give it.\""}, {"id": "B", "text": "\"Give it slowly over two minutes and record the blood pressure afterwards.\""}, {"id": "C", "text": "\"I will give the intravenous dose myself. Would you record the observations for that client instead?\""}, {"id": "D", "text": "\"Wait until I have finished the admission and then give it under my direct supervision.\""}]}'::jsonb,
 '{"answer": "C", "feedback": {"A": "Incorrect. Checking the dose does not bring the administration inside the scope of the licensed practical nurse.", "B": "Incorrect. This directs the licensed practical nurse to perform a task outside the permitted scope.", "C": "Correct. The registered nurse retains the intravenous push dose and delegates a task that is within scope.", "D": "Incorrect. Supervision does not extend a scope of practice; the task remains outside it."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to the licensed practical nurse', 'Intravenous push medication',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MAT_530004', 'MATRIX', 'A registered nurse is deciding how to allocate the work on a medical ward. For each task, indicate whether it is within the scope of the licensed practical nurse or whether it requires the registered nurse.', 'The dividing line is nursing judgement. Tasks that follow an established plan on a stable client - giving an intramuscular antibiotic, reinforcing teaching already given, recording and reporting an intake and output chart - sit with the licensed practical nurse. Anything that is a first (a first dose, a first assessment after a transfer) or that carries a high immediate risk (central venous access) stays with the registered nurse.',
 '{"rows": [{"id": "r1", "text": "Administering a prescribed intramuscular antibiotic to a stable client"}, {"id": "r2", "text": "Changing the dressing over a central venous catheter"}, {"id": "r3", "text": "Reinforcing teaching about a low-salt diet that has already been given"}, {"id": "r4", "text": "Assessing a client who has just been transferred from the intensive care unit"}, {"id": "r5", "text": "Recording an intake and output chart and reporting the totals"}, {"id": "r6", "text": "Giving the first dose of a newly prescribed intravenous antibiotic"}], "columns": [{"id": "c1", "text": "Within the scope of the licensed practical nurse"}, {"id": "c2", "text": "Requires the registered nurse"}], "row_label": "Task"}'::jsonb,
 '{"cells": {"r1": "c1", "r2": "c2", "r3": "c1", "r4": "c2", "r5": "c1", "r6": "c2"}, "feedback": {}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to the licensed practical nurse', 'Scope decisions',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select one column for each row.', 6, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530005', 'MCQ', 'A registered nurse walks into a bay and sees a licensed practical nurse connecting the first unit of packed red cells to the cannula of a client whose haemoglobin is 6.4 g/dL. Which action should the nurse take?', 'Administering a blood product is a registered nurse responsibility, and the first fifteen minutes of a transfusion is when a haemolytic reaction is most likely to declare itself. This is the immediate-danger branch of the escalation rule: the nurse intervenes at the point of care and takes over the task. The conversation about scope happens afterwards, away from the client.',
 '{"options": [{"id": "A", "text": "Stop the licensed practical nurse and take over the transfusion personally"}, {"id": "B", "text": "Remind the licensed practical nurse to record the observations 15 minutes after the start"}, {"id": "C", "text": "Ask the licensed practical nurse to collect the second unit from the blood fridge"}, {"id": "D", "text": "Document that the transfusion was commenced and continue the medication round"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. A client is placed at immediate risk, so the nurse intervenes at once and takes over the task.", "B": "Incorrect. This allows an out-of-scope task to continue and addresses only the monitoring.", "C": "Incorrect. This compounds the breach by involving the licensed practical nurse further in the transfusion.", "D": "Incorrect. Documenting an unsafe act without stopping it leaves the client exposed to a transfusion reaction."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem', 'Staff behaviour escalation', 'Intervening at the point of care',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SELN_530006', 'SELECT_N', 'A charge nurse is allocating clients on a medical ward. Which 3 clients may be assigned to a licensed practical nurse?', 'A licensed practical nurse is assigned clients whose condition is stable and whose outcome is predictable. A client who has not yet been assessed, a client on a titrated infusion and a client in the immediate period after surgery all require the ongoing assessment and judgement of a registered nurse, so none of them may be assigned.',
 '{"options": [{"id": "A", "text": "A client on the third day after a laparoscopic cholecystectomy who is waiting for transport home"}, {"id": "B", "text": "A client with chronic obstructive pulmonary disease on 2 litres of oxygen per minute whose condition has been unchanged for two days"}, {"id": "C", "text": "A client with a long-standing colostomy who needs help with a routine bag change"}, {"id": "D", "text": "A client admitted one hour ago with abdominal pain who has not yet been assessed"}, {"id": "E", "text": "A client receiving a continuous heparin infusion titrated to the aPTT"}, {"id": "F", "text": "A client who returned from theatre 20 minutes ago after a thyroidectomy"}], "select_count": 3}'::jsonb,
 '{"answers": ["A", "B", "C"], "feedback": {"A": "Correct. This client is stable and awaiting discharge, with a predictable outcome.", "B": "Correct. A chronic condition that has been unchanged for two days is stable and suitable.", "C": "Correct. Routine stoma care on an established stoma follows a known plan.", "D": "Incorrect. The first assessment of a new admission cannot be delegated.", "E": "Incorrect. A titrated infusion requires continuous registered nurse assessment and dose adjustment.", "F": "Incorrect. The period immediately after a thyroidectomy carries a risk of airway obstruction and haemorrhage."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Assignment decisions', 'Matching client acuity to the licensed practical nurse',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_TF_530007', 'TF', 'A licensed practical nurse may reinforce teaching about a low-salt diet that the registered nurse has already provided to a client with heart failure. True or false?', 'Teaching has two halves. Assessing what the client needs to learn and delivering the first explanation belong to the registered nurse, because both require assessment and a plan. Repeating, reinforcing and checking back on teaching that has already been delivered is within the scope of the licensed practical nurse.',
 '{"options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Reinforcement of teaching already delivered is within the scope of the licensed practical nurse.", "B": "Incorrect. Only the initial teaching is restricted to the registered nurse; reinforcement may be delegated."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to the licensed practical nurse', 'Reinforcing teaching',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530008', 'MCQ', 'A client admitted with an ischaemic stroke has been assessed by the speech and language therapist and cleared for a soft diet. A licensed practical nurse offers to give the client the first meal. Which response by the registered nurse is correct?', 'The first of anything belongs to the registered nurse. A swallow that is safe in a therapy assessment may not be safe at the bedside with a full tray, so the first feed is an evaluation of the plan, not simply a task. Once the client has been observed swallowing safely and the response documented, later meals may be given by the licensed practical nurse.',
 '{"options": [{"id": "A", "text": "\"Please go ahead - the therapist has already cleared the client.\""}, {"id": "B", "text": "\"I will give this first meal and observe the swallowing. You may give the later meals.\""}, {"id": "C", "text": "\"Ask the healthcare assistant to feed the client and to stay in the bay throughout.\""}, {"id": "D", "text": "\"Keep the client nil by mouth until the therapist reviews again tomorrow.\""}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Clearance by the therapist does not remove the need for the registered nurse to evaluate the first feed.", "B": "Correct. The registered nurse carries out and evaluates the first feed; subsequent meals may then be delegated.", "C": "Incorrect. A first feed after a stroke requires assessment of the swallow, which cannot be delegated to assistive personnel.", "D": "Incorrect. Withholding a diet that has been cleared delays nutrition without any clinical justification."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem', 'The first of anything', 'First feed after a stroke',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530009', 'SATA', 'A registered nurse is planning the shift with a licensed practical nurse and a healthcare assistant. Which activities must the registered nurse carry out personally? Select all that apply.', 'Four assessments can never be delegated: admission, discharge, transfer, and the first assessment after any change in condition. To those add the first performance of any new intervention and the initial teaching for a new treatment, because each is an evaluation rather than a routine task. Repeat observations on a stable client, personal care and reinforcement of teaching already given may all be delegated.',
 '{"options": [{"id": "A", "text": "The admission assessment of a client arriving from the emergency department"}, {"id": "B", "text": "The first set of observations for a client who has just returned from theatre"}, {"id": "C", "text": "The assessment of a client whose confusion has increased over the past hour"}, {"id": "D", "text": "The discharge teaching for a client starting warfarin"}, {"id": "E", "text": "The routine four-hourly observations for a stable client on day three after surgery"}, {"id": "F", "text": "Assisting a stable client with a bed bath"}, {"id": "G", "text": "Reinforcing crutch walking that has already been taught to a stable client"}]}'::jsonb,
 '{"answers": ["A", "B", "C", "D"], "feedback": {"A": "Correct. An admission assessment establishes the baseline and the plan of care, so it cannot be delegated.", "B": "Correct. The first observation set after theatre is a first, and it establishes the post-operative baseline.", "C": "Correct. The first assessment after a change in condition belongs to the registered nurse.", "D": "Correct. Initial teaching for a new medication is an assessment of learning needs as well as an explanation.", "E": "Incorrect. Repeat observations on a stable client may be delegated with clear reporting parameters.", "F": "Incorrect. Assisting with hygiene for a stable client is standard assistive personnel work.", "G": "Incorrect. Reinforcement of teaching already delivered may be delegated."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Assessment that cannot be delegated', 'Admission, discharge, transfer and change',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_CLZ_530010', 'CLOZE', 'A client is on the first day after a total hip replacement. The first time the client stands and walks is supervised by the {1}. Once the client has walked safely and the response has been evaluated, later walks on the same day may be delegated to the {2}.', 'A first mobilisation after joint replacement carries a real risk of dislocation, orthostatic hypotension and falling, so it is an assessment as much as a walk. The registered nurse, usually alongside the physiotherapist, carries out that first walk and evaluates how the client tolerated it. Once tolerance is established and the plan is set, subsequent walks are a routine task that assistive personnel may carry out.',
 '{"blanks": [{"id": "b1", "choices": [{"id": "c1", "text": "registered nurse together with the physiotherapist"}, {"id": "c2", "text": "healthcare assistant"}, {"id": "c3", "text": "visiting relative"}]}, {"id": "b2", "choices": [{"id": "c4", "text": "healthcare assistant"}, {"id": "c5", "text": "client, walking alone without supervision"}, {"id": "c6", "text": "physiotherapist only, as walking may never be delegated"}]}]}'::jsonb,
 '{"answers": {"b1": "c1", "b2": "c4"}, "feedback": {}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem', 'The first of anything', 'First ambulation after hip replacement',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Complete the sentence by choosing from each drop-down.', 2, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_530011', 'MCQ', 'A client on a respiratory ward tells a healthcare assistant that he has become breathless while sitting in the chair. The healthcare assistant reports this to the registered nurse and offers to record a set of observations. Which action by the nurse is most appropriate?', 'A change in condition triggers an assessment, and assessment cannot be delegated. Observations recorded by assistive personnel are a set of numbers; they do not capture work of breathing, air entry, colour or the ability of the client to speak in sentences. The nurse goes to the client, assesses personally, and only then decides what to do next.',
 '{"options": [{"id": "A", "text": "Ask the healthcare assistant to record the observations and report them back"}, {"id": "B", "text": "Go to the client and carry out an assessment personally"}, {"id": "C", "text": "Ask the licensed practical nurse to review the client after the medication round"}, {"id": "D", "text": "Telephone the provider to report that the client has become breathless"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Numbers alone do not describe respiratory effort, and the assessment cannot be delegated.", "B": "Correct. The first assessment after a change in condition is carried out by the registered nurse.", "C": "Incorrect. This both delegates an assessment and delays it until after the drug round.", "D": "Incorrect. Calling the provider before assessing means reporting without any current findings."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem', 'Assessment that cannot be delegated', 'Change in condition',
 'Hard', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_CLZ_530012', 'CLOZE', 'A client is admitted to a medical ward at 14:00. The admission assessment must be completed by the {1}. The routine four-hourly observations that follow may be recorded by the {2}, who reports the readings to the nurse without interpreting them.', 'The admission assessment sets the baseline and generates the plan of care, so it belongs to the registered nurse alone. Once the plan exists, the repeat observations that follow are a routine measurement with a predictable outcome and may be delegated. The person who records them reports the numbers; deciding what those numbers mean stays with the nurse.',
 '{"blanks": [{"id": "b1", "choices": [{"id": "c1", "text": "registered nurse"}, {"id": "c2", "text": "licensed practical nurse"}, {"id": "c3", "text": "healthcare assistant"}]}, {"id": "b2", "choices": [{"id": "c4", "text": "healthcare assistant"}, {"id": "c5", "text": "registered nurse only"}, {"id": "c6", "text": "ward clerk"}]}]}'::jsonb,
 '{"answers": {"b1": "c1", "b2": "c4"}, "feedback": {}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Assessment that cannot be delegated', 'Admission assessment',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 'Complete the sentence by choosing from each drop-down.', 2, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530013', 'MCQ', 'A registered nurse is working with a healthcare assistant on a busy medical ward. Which task is appropriate to delegate to the healthcare assistant?', 'Assistive personnel collect data; they do not interpret it. Recording a set of observations on a stable client and reporting the readings is a standardised task with a predictable outcome. Deciding what a reading means, teaching a new skill and revising a plan of care are all nursing judgement and stay with the registered nurse.',
 '{"options": [{"id": "A", "text": "Recording the blood pressure, pulse and temperature of a stable client and reporting the readings"}, {"id": "B", "text": "Deciding whether a blood pressure of 92/54 mmHg needs to be reported to the provider"}, {"id": "C", "text": "Explaining to a newly diagnosed client how to use a metered dose inhaler"}, {"id": "D", "text": "Revising the plan of care after a change in the condition of a client"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Measuring and reporting observations on a stable client is a delegable task.", "B": "Incorrect. Interpreting a reading and deciding to escalate is nursing judgement.", "C": "Incorrect. Initial teaching requires assessment of learning needs and belongs to the nurse.", "D": "Incorrect. The plan of care is created and revised by the registered nurse."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to assistive personnel', 'Data collection versus interpretation',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530014', 'SATA', 'A registered nurse is delegating work to an experienced healthcare assistant. Which tasks may be delegated? Select all that apply.', 'Delegable tasks share a shape: routine, standardised, low risk, predictable outcome, and no assessment required while they are carried out. Hygiene, measuring a capillary blood glucose, emptying a catheter bag and applying a barrier preparation to intact skin all fit. Applying a prescription topical with systemic effects, and judging whether a pressure area has deteriorated, do not.',
 '{"options": [{"id": "A", "text": "Measuring a capillary blood glucose and reporting the result to the nurse"}, {"id": "B", "text": "Assisting a stable client to shower"}, {"id": "C", "text": "Applying a zinc-based barrier cream to intact skin"}, {"id": "D", "text": "Emptying a urinary catheter bag and recording the volume"}, {"id": "E", "text": "Applying nitroglycerin ointment to the chest wall of a client with angina"}, {"id": "F", "text": "Deciding whether a pressure area has deteriorated since yesterday"}]}'::jsonb,
 '{"answers": ["A", "B", "C", "D"], "feedback": {"A": "Correct. Obtaining the value may be delegated; interpreting it and acting on it may not.", "B": "Correct. Assisting a stable client with hygiene is standard assistive personnel work.", "C": "Correct. A barrier preparation applied to intact skin is a low-risk, over-the-counter product.", "D": "Correct. Emptying and measuring drainage is a routine task with a predictable outcome.", "E": "Incorrect. Nitroglycerin is a prescription topical with systemic effects and is administered by a nurse.", "F": "Incorrect. Evaluating a wound or pressure area is an assessment and cannot be delegated."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to assistive personnel', 'Delegable tasks',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530015', 'MCQ', 'A registered nurse is caring for four clients who have skin preparations prescribed. Which preparation may the nurse ask an experienced healthcare assistant to apply?', 'Topical preparations divide by what they do rather than by where they go. Barrier and other over-the-counter products applied to intact skin protect the skin and carry no systemic effect, so they may be delegated. Prescription topicals - nitroglycerin, antibiotic ointment, corticosteroids - are medications: they require assessment of the site, correct dose and site rotation, and produce systemic effects.',
 '{"options": [{"id": "A", "text": "Nitroglycerin ointment to the chest wall of a client with angina"}, {"id": "B", "text": "A zinc-based barrier cream to the intact skin of an incontinent client"}, {"id": "C", "text": "Mupirocin antibiotic ointment to the edge of a surgical wound"}, {"id": "D", "text": "A topical corticosteroid to an inflamed patch of eczema"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Nitroglycerin ointment is a prescribed medication with systemic effects on blood pressure.", "B": "Correct. A barrier preparation on intact skin is an over-the-counter product and may be delegated.", "C": "Incorrect. An antibiotic ointment is a prescribed medication and the wound requires assessment.", "D": "Incorrect. A topical corticosteroid is a prescribed medication applied to broken or inflamed skin."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to assistive personnel', 'Topical preparations',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530016', 'MCQ', 'A client on a surgical ward is prescribed a tap-water cleansing enema before an investigation. The team consists of one registered nurse, one licensed practical nurse and an experienced healthcare assistant who has been assessed as competent in the procedure. Which statement is correct?', 'A cleansing enema for a stable client is a standardised procedure with a predictable outcome, and it may be delegated to assistive personnel who have been assessed as competent in it. What cannot be delegated is the judgement wrapped around it: evaluating the result, deciding whether a second enema is needed and deciding whether the client has tolerated it all remain with the registered nurse.',
 '{"options": [{"id": "A", "text": "The enema may be given by the healthcare assistant, who reports the result to the registered nurse"}, {"id": "B", "text": "The enema may only be given by the registered nurse because it is an invasive procedure"}, {"id": "C", "text": "The enema may be delegated, and the healthcare assistant may decide whether a second one is needed"}, {"id": "D", "text": "The enema must be given by the licensed practical nurse, as assistive personnel may not carry out bowel care"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. The procedure is delegable to competent assistive personnel; the result is reported to the nurse.", "B": "Incorrect. A cleansing enema for a stable client is a standardised task and may be delegated.", "C": "Incorrect. The task may be delegated but the decision to repeat it is nursing judgement.", "D": "Incorrect. Assistive personnel who have been assessed as competent may administer a cleansing enema."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to assistive personnel', 'Enema administration',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530017', 'SATA', 'A registered nurse reviews the entries a healthcare assistant has made in the records of several clients. Which entries require the nurse to follow up with the healthcare assistant? Select all that apply.', 'Assistive personnel document what they did and what they measured, not what they concluded. An entry such as "dehydrated" or "looks infected" is a nursing diagnosis reached without the assessment that supports it, and it may be relied on later by someone who does not realise who wrote it. Entries that record an action, a measurement or a reported observation are appropriate.',
 '{"options": [{"id": "A", "text": "\"Client is dehydrated.\""}, {"id": "B", "text": "\"Client drank 150 mL of water at 10:00.\""}, {"id": "C", "text": "\"Wound looks infected.\""}, {"id": "D", "text": "\"Client walked to the bathroom with a frame and returned to the chair.\""}, {"id": "E", "text": "\"Client appears to be going into heart failure.\""}, {"id": "F", "text": "\"Blood pressure 118/72 mmHg, pulse 78 beats per minute, reported to the nurse.\""}]}'::jsonb,
 '{"answers": ["A", "C", "E"], "feedback": {"A": "Correct. This is a conclusion about the client rather than a record of what was observed or done.", "B": "Incorrect. This records a measured intake and is appropriate documentation.", "C": "Correct. Judging that a wound is infected is an assessment outside the assistive personnel role.", "D": "Incorrect. This records what the healthcare assistant did and what happened.", "E": "Correct. This is a clinical conclusion that requires nursing assessment and diagnosis.", "F": "Incorrect. Recording measured values and reporting them to the nurse is exactly the expected entry."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to assistive personnel', 'Documentation by assistive personnel',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530018', 'MCQ', 'A healthcare assistant tells the registered nurse, "The blood pressure for the lady in bed 2 was 88/50 mmHg, but she always runs low so I did not think it mattered." The client is receiving intravenous furosemide. Which action should the nurse take?', 'Two things have gone wrong: a reading outside the normal range was not reported promptly, and it was interpreted by someone whose role does not include interpretation. The client is on a loop diuretic and may be hypovolaemic, so the nurse assesses personally and at once. Teaching the healthcare assistant about reporting parameters is necessary but follows the assessment.',
 '{"options": [{"id": "A", "text": "Ask the healthcare assistant to repeat the blood pressure in one hour"}, {"id": "B", "text": "Go to the client and carry out an assessment"}, {"id": "C", "text": "Explain that low readings must always be reported, then continue the medication round"}, {"id": "D", "text": "Document the reading and inform the provider at the ward round"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Delaying an hour leaves a possibly hypovolaemic client unassessed.", "B": "Correct. The nurse assesses the client personally, because interpretation and assessment are nursing responsibilities.", "C": "Incorrect. The teaching point is valid but the client has not yet been assessed.", "D": "Incorrect. Documenting and waiting for the ward round delays assessment of a low blood pressure."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem', 'Delegation to assistive personnel', 'Reporting versus interpreting',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MMR_530019', 'MATRIX_MR', 'A registered nurse is planning the work of a team that includes a licensed practical nurse and a healthcare assistant. For each task, select every team member who may carry it out.', 'Scope widens as risk and judgement fall. Personal care and routine measurement on a stable client are open to all three team members. Medication administration by an oral or intramuscular route, and the reinforcement of teaching, open to the nurse and the licensed practical nurse. Creating the plan of care and giving an intravenous push dose belong to the registered nurse alone.',
 '{"rows": [{"id": "r1", "text": "Administering a prescribed oral laxative"}, {"id": "r2", "text": "Recording a set of routine observations on a stable client"}, {"id": "r3", "text": "Creating the plan of care for a newly admitted client"}, {"id": "r4", "text": "Reinforcing pursed-lip breathing that the registered nurse has already taught"}, {"id": "r5", "text": "Assisting a stable client with mouth care"}, {"id": "r6", "text": "Administering an intravenous push dose of morphine"}], "columns": [{"id": "c1", "text": "Registered nurse"}, {"id": "c2", "text": "Licensed practical nurse"}, {"id": "c3", "text": "Healthcare assistant"}], "row_label": "Task"}'::jsonb,
 '{"cells": {"r1": ["c1", "c2"], "r2": ["c1", "c2", "c3"], "r3": ["c1"], "r4": ["c1", "c2"], "r5": ["c1", "c2", "c3"], "r6": ["c1"]}, "feedback": {}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Skill mix', 'Who may perform each task',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply for each row.', 12, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530020', 'MCQ', 'A registered nurse asks a healthcare assistant to measure the capillary blood glucose of four clients before breakfast. Which additional instruction is essential?', 'The right direction and communication means the person carrying out the task knows exactly what to report, to whom and by when. Assistive personnel may obtain a capillary blood glucose, but the interpretation of the value and any insulin decision remain with the nurse. Setting an explicit threshold for immediate reporting turns a task into a safe delegation.',
 '{"options": [{"id": "A", "text": "\"Give the insulin once you have the reading if it is above 7 mmol/L.\""}, {"id": "B", "text": "\"Report every reading to me before any insulin is given, and tell me at once if a reading is below 4 mmol/L.\""}, {"id": "C", "text": "\"Record the readings in the chart and I will look at them after the drug round.\""}, {"id": "D", "text": "\"Repeat any reading that looks too high or too low before you tell me.\""}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Insulin administration and the decision to give it are nursing responsibilities.", "B": "Correct. This states what to report, to whom and the threshold for reporting immediately.", "C": "Incorrect. A reading of concern would not reach the nurse until after the drug round.", "D": "Incorrect. Deciding that a reading is implausible is interpretation and delays reporting."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Five rights of delegation', 'Right direction and communication',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_SELN_530021', 'SELECT_N', 'A registered nurse begins a shift with six clients and one healthcare assistant. Which 3 tasks should the nurse delegate to the healthcare assistant?', 'Delegation frees nursing time for the work that only a nurse may do. Hygiene, weighing a client and escorting a stable client for an investigation are routine tasks with predictable outcomes. Teaching, checking understanding of a discharge medication and assessing new leg pain all require nursing judgement and must be kept.',
 '{"options": [{"id": "A", "text": "Assist a stable client with a bed bath"}, {"id": "B", "text": "Record the daily weight of a client with heart failure"}, {"id": "C", "text": "Escort a stable client to the radiology department in a wheelchair"}, {"id": "D", "text": "Teach a client how to keep a fluid balance chart at home"}, {"id": "E", "text": "Check whether a client understands the new discharge medication"}, {"id": "F", "text": "Assess the calf of a client who reports new leg pain"}], "select_count": 3}'::jsonb,
 '{"answers": ["A", "B", "C"], "feedback": {"A": "Correct. Hygiene for a stable client is a routine delegable task.", "B": "Correct. Weighing a client is a measurement; interpreting the trend remains with the nurse.", "C": "Correct. Escorting a stable client is a routine task with a predictable outcome.", "D": "Incorrect. Teaching a new skill requires assessment of learning needs.", "E": "Incorrect. Evaluating understanding of medication is a nursing evaluation.", "F": "Incorrect. New leg pain requires assessment, which cannot be delegated."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegation to assistive personnel', 'Choosing what to delegate',
 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530022', 'MCQ', 'A registered nurse has delegated four tasks to a healthcare assistant at the start of a shift. Which action by the nurse best demonstrates the right supervision, the fifth right of delegation?', 'Supervision is the right that is most often skipped. It means agreeing when the person will report back, being available while the task is carried out, checking the completed work, and evaluating the outcome for the client. Assuming that silence means success converts delegation into abandonment of the task.',
 '{"options": [{"id": "A", "text": "Agreeing set times for the healthcare assistant to report back and checking the completed work during the shift"}, {"id": "B", "text": "Assuming the tasks have been completed correctly unless the healthcare assistant says otherwise"}, {"id": "C", "text": "Repeating the same instructions to the oncoming nurse at handover"}, {"id": "D", "text": "Asking a second healthcare assistant to check the work of the first"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Agreed reporting times plus a personal check of the work is what supervision means.", "B": "Incorrect. Silence is not evidence that a task was done, or done safely.", "C": "Incorrect. Handover passes the information on but does not supervise the task now.", "D": "Incorrect. Supervision of a delegated task is the responsibility of the nurse who delegated it."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Five rights of delegation', 'Right supervision',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530023', 'SATA', 'Which statements by a charge nurse show a correct understanding of accountability in delegation? Select all that apply.', 'A nurse may delegate a task but never the accountability for the outcome of that task, nor the nursing process that surrounds it. Accountability is discharged by choosing a competent person, giving clear direction, supervising and evaluating. It is not transferred by handing the task over, and a poor outcome is examined as a delegation decision as well as a performance issue.',
 '{"options": [{"id": "A", "text": "\"When I delegate a task I remain accountable for the outcome of that task.\""}, {"id": "B", "text": "\"I must satisfy myself that the person I delegate to is competent to perform the task.\""}, {"id": "C", "text": "\"Once a task is delegated, responsibility for that client passes to the healthcare assistant.\""}, {"id": "D", "text": "\"I need to follow up during the shift and evaluate the result for the client.\""}, {"id": "E", "text": "\"Delegating a task also delegates the nursing assessment that goes with it.\""}, {"id": "F", "text": "\"If a delegated task is done unsafely, that is entirely the fault of the person who did it.\""}]}'::jsonb,
 '{"answers": ["A", "B", "D"], "feedback": {"A": "Correct. Accountability for the outcome stays with the nurse who delegated the task.", "B": "Correct. Matching the task to demonstrated competence is part of accountability.", "C": "Incorrect. Responsibility for the client is never transferred by delegating a task.", "D": "Correct. Following up and evaluating the result completes the delegation.", "E": "Incorrect. Assessment is never delegated, whatever task goes with it.", "F": "Incorrect. The delegation decision itself is examined, so the nurse is not absolved."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Accountability in delegation', 'Retaining accountability',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 'Select all that apply.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_DO_530024', 'DRAG_ORDER', 'A registered nurse is about to delegate the routine observations for four stable clients to a healthcare assistant. Place the steps of safe delegation in the order in which the nurse should carry them out.', 'Safe delegation runs in a fixed order: decide whether the task is delegable for this client, choose a person whose competence matches it, give direction that includes what to report and when, confirm that the direction has been understood, then supervise and evaluate. Skipping the confirmation step is the commonest cause of a delegated task going wrong, because the nurse only discovers the misunderstanding after the event.',
 '{"slots": [{"id": "s1", "target_text": "1st"}, {"id": "s2", "target_text": "2nd"}, {"id": "s3", "target_text": "3rd"}, {"id": "s4", "target_text": "4th"}, {"id": "s5", "target_text": "5th"}], "tokens": [{"id": "t1", "text": "Decide that the task is suitable for delegation and that the client is stable"}, {"id": "t2", "text": "Select a person whose assessed competence matches the task"}, {"id": "t3", "text": "Give clear direction, including what to report and by when"}, {"id": "t4", "text": "Ask the person to state back what has been agreed"}, {"id": "t5", "text": "Supervise during the shift and evaluate the outcome"}, {"id": "t6", "text": "Record the delegated task in the discharge summary"}]}'::jsonb,
 '{"slots": {"s1": "t1", "s2": "t2", "s3": "t3", "s4": "t4", "s5": "t5"}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Five rights of delegation', 'Sequence of safe delegation',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Place the options in the correct order.', 5, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530025', 'SATA', 'A registered nurse is deciding whether a task may be delegated to a healthcare assistant. Which conditions must be met? Select all that apply.', 'The right circumstance and the right person are tested before the task is handed over, not afterwards. The outcome must be predictable for this client, the task must not require assessment or judgement while it is carried out, the person must have demonstrated competence in it, and the nurse must be available to supervise. Being short-staffed and being willing to try are not part of the test.',
 '{"options": [{"id": "A", "text": "The outcome of the task is predictable for this particular client"}, {"id": "B", "text": "The task does not require nursing assessment or judgement while it is being carried out"}, {"id": "C", "text": "The person delegated to has demonstrated competence in the task"}, {"id": "D", "text": "The registered nurse is available to supervise and can be contacted"}, {"id": "E", "text": "The unit is short-staffed, so the work has to be shared out"}, {"id": "F", "text": "The person delegated to is willing to attempt the task for the first time"}]}'::jsonb,
 '{"answers": ["A", "B", "C", "D"], "feedback": {"A": "Correct. An unpredictable outcome means the task needs nursing judgement and cannot be delegated.", "B": "Correct. If judgement is needed part-way through, the task belongs to the nurse.", "C": "Correct. Job title alone is not competence; the person must have demonstrated the skill.", "D": "Correct. Delegation without available supervision is abandonment of the task.", "E": "Incorrect. Staffing pressure never widens a scope of practice.", "F": "Incorrect. Willingness is not competence, and a first attempt requires teaching and direct supervision."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Five rights of delegation', 'Right circumstance and right person',
 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530026', 'MCQ', 'A registered nurse sees a first-year nursing student, who is not permitted to administer intravenous medication, connecting an antibiotic infusion to the cannula of a client. Which action should the nurse take?', 'A client is about to receive a medication from someone who is not permitted to give it and who has not been assessed as competent to do so. That is immediate physical danger, and the response to immediate danger is to intervene at the point of care and take over the task. Teaching the student and informing the clinical instructor both follow; neither replaces stopping the act.',
 '{"options": [{"id": "A", "text": "Stop the student immediately and complete the connection personally"}, {"id": "B", "text": "Watch from the doorway and speak to the student about it afterwards"}, {"id": "C", "text": "Ask the student to fetch the clinical instructor before continuing"}, {"id": "D", "text": "Report the student to the university link tutor at the end of the shift"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Immediate danger to a client is met by intervening at once and taking over the task.", "B": "Incorrect. Observing allows the medication to be given by someone not permitted to give it.", "C": "Incorrect. This leaves the infusion connected and the client unsupervised while the student is away.", "D": "Incorrect. Reporting later does nothing about the medication being given now."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Supervising students', 'Intervening mid-task',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530027', 'MCQ', 'A nursing student is inserting a urinary catheter under supervision. While reaching for the drainage bag the student touches the catheter tip against the bed linen. Which action should the registered nurse take FIRST?', 'FIRST is a question about sequence. Nothing else can safely happen until the contaminated catheter is prevented from entering the urethra, so the immediate action is to stop the student. Replacing the equipment, explaining the delay to the client and teaching the student about the boundaries of a sterile field all matter, but each of them takes seconds during which an unstopped student may complete the insertion.',
 '{"options": [{"id": "A", "text": "Tell the student to stop and not to insert the catheter"}, {"id": "B", "text": "Open a new sterile catheterisation pack and set up again"}, {"id": "C", "text": "Explain to the client that the procedure will take a little longer"}, {"id": "D", "text": "Ask the student to describe what has just happened"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Stopping the insertion is the only action that prevents the contaminated catheter reaching the client.", "B": "Incorrect. This is the right next step but the student may insert the catheter while the nurse opens the pack.", "C": "Incorrect. The client does need an explanation, but not before the unsafe act is halted.", "D": "Incorrect. Reflection is valuable teaching but it does not stop the procedure."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Supervising students', 'Broken sterile field',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530028', 'MCQ', 'A nursing student touched the catheter tip against the bed linen while inserting a urinary catheter, and the registered nurse has stopped the procedure. Which action is the PRIORITY?', 'PRIORITY is a question about what matters most rather than what happens first. What matters most to this client is that a contaminated catheter never enters the bladder, so the equipment is discarded and the procedure restarted with a sterile set. Documentation, teaching and a conversation about supervision are all required, but none of them protects the client from a catheter-associated urinary tract infection.',
 '{"options": [{"id": "A", "text": "Discard the contaminated catheter and restart with a new sterile pack"}, {"id": "B", "text": "Document the break in technique in the clinical record"}, {"id": "C", "text": "Teach the student about the boundaries of a sterile field"}, {"id": "D", "text": "Inform the clinical instructor that closer supervision is needed"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Preventing a catheter-associated infection is what matters most for this client.", "B": "Incorrect. Documentation is required but does not reduce the risk to the client.", "C": "Incorrect. The teaching is necessary and should follow, once the client is safe.", "D": "Incorrect. Adjusting supervision is a later decision about the student, not the client."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Supervising students', 'Broken sterile field',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530029', 'MCQ', 'At the nurses station a newly qualified nurse laughs and makes a mocking remark about the weight of a client. No client or relative is within hearing. Which action should the registered nurse take?', 'Behaviour that is unprofessional but causes no immediate harm sits in the third branch of the escalation rule: it is addressed privately, promptly and directly by the colleague who saw it. Ignoring it normalises it, and correcting a colleague publicly humiliates without teaching. Escalation to the manager is reserved for illegal conduct or for behaviour that continues after it has been addressed.',
 '{"options": [{"id": "A", "text": "Ignore the remark, as no client heard it"}, {"id": "B", "text": "Speak to the nurse privately later in the shift about the effect of such remarks"}, {"id": "C", "text": "Correct the nurse at the station so that the whole team hears the standard expected"}, {"id": "D", "text": "Report the nurse to the nurse manager for disciplinary action"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. Unprofessional behaviour is never ignored, whether or not a client heard it.", "B": "Correct. Harmless but unprofessional behaviour is addressed privately and promptly.", "C": "Incorrect. A public reprimand humiliates the colleague and does not change behaviour.", "D": "Incorrect. Escalation to the manager is reserved for illegal conduct or repeated behaviour."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Staff behaviour escalation', 'Unprofessional but harmless conduct',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530030', 'MCQ', 'A nurse notices that a colleague on the same shift smells of alcohol, has slurred speech and is unsteady while preparing the morning medications. Which action should the nurse take?', 'A colleague who appears to be under the influence places every client on that round in immediate danger, so the response is to intervene at once and take over the task rather than to observe or to wait. The colleague is removed from client care and the nurse manager is informed straight away, because this is also conduct that must be reported. Asking the colleague whether she feels well enough to continue leaves the decision with the impaired person.',
 '{"options": [{"id": "A", "text": "Take over the medication round at once and ask the colleague to stop clinical work"}, {"id": "B", "text": "Ask the colleague whether she feels well enough to continue the round"}, {"id": "C", "text": "Complete the round together and speak to the nurse manager at the end of the shift"}, {"id": "D", "text": "Say nothing but check every medication the colleague gives"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Immediate danger to clients is met by intervening at once and taking over the task.", "B": "Incorrect. An impaired colleague is not able to judge her own fitness to practise.", "C": "Incorrect. Waiting until the end of the shift leaves clients exposed for several hours.", "D": "Incorrect. Silent double-checking does not remove the danger and conceals reportable conduct."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Staff behaviour escalation', 'Colleague under the influence',
 'Easy', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_530031', 'MCQ', 'At the end of a shift the controlled drug count does not reconcile. Three doses of oxycodone are signed out to one nurse for a client who has told the ward that he has had no pain relief all day. Which action should the nurse take FIRST?', 'Suspected diversion of a controlled drug is illegal conduct, and the route for illegal conduct is a report to the supervisor. Reporting FIRST matters because an individual nurse who investigates alone may destroy the record trail, warn the colleague or create a personal safety risk. The register is never altered to make the stock agree; the discrepancy is the evidence.',
 '{"options": [{"id": "A", "text": "Report the discrepancy to the nurse manager"}, {"id": "B", "text": "Ask the colleague to explain what happened to the missing doses"}, {"id": "C", "text": "Adjust the controlled drug register so that it matches the stock in the cupboard"}, {"id": "D", "text": "Complete an incident report and hand it in at the end of the week"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Suspected diversion is reported to the supervisor, who begins a formal investigation.", "B": "Incorrect. Confronting the colleague may destroy evidence and is not the role of the individual nurse.", "C": "Incorrect. Altering the register conceals the discrepancy and is itself falsification of a record.", "D": "Incorrect. A delayed report leaves clients without analgesia and the drug supply unprotected."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Staff behaviour escalation', 'Suspected controlled drug diversion',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530032', 'MCQ', 'A nurse has reported to the nurse manager that controlled drug doses signed out by a colleague appear not to have reached the clients. The manager has started an investigation. Which action is the PRIORITY for the nurse on the ward?', 'Once the report has been made, the investigation belongs to the manager. What matters most on the ward is the group of clients who may have gone without prescribed analgesia: they are assessed, their pain is treated and the response is documented. Gathering statements, copying registers or warning the colleague are not nursing actions and the last of them obstructs the investigation.',
 '{"options": [{"id": "A", "text": "Assess the clients whose analgesia is in question and ensure their pain is treated"}, {"id": "B", "text": "Ask the other nurses on the shift what they saw during the day"}, {"id": "C", "text": "Photocopy the controlled drug register pages for the manager"}, {"id": "D", "text": "Warn the colleague that an investigation has begun"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Clients who may have received no analgesia are what matters most now.", "B": "Incorrect. Collecting statements is the role of the manager conducting the investigation.", "C": "Incorrect. Handling the records independently risks compromising the evidence.", "D": "Incorrect. Warning the colleague obstructs the investigation and is a professional breach."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Staff behaviour escalation', 'Client safety during an investigation',
 'Hard', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MAT_530033', 'MATRIX', 'A registered nurse observes several behaviours during one shift. For each behaviour, indicate the response the nurse should make.', 'Three branches cover almost every staff behaviour question. Anyone in immediate physical or psychological danger means the nurse intervenes at the point of care and takes over the task. Illegal conduct - falsified records, suspected diversion - is reported to the supervisor rather than handled privately. Behaviour that is unprofessional but harmless is addressed privately and promptly. Nothing is ignored.',
 '{"rows": [{"id": "r1", "text": "A nurse begins a sterile dressing change without hand hygiene or gloves"}, {"id": "r2", "text": "A nurse documents a set of observations that was never taken"}, {"id": "r3", "text": "A healthcare assistant chews gum and chats casually while assisting a client to wash"}, {"id": "r4", "text": "A nurse who appears intoxicated is drawing up an intravenous medication"}, {"id": "r5", "text": "A nurse signs out a controlled drug that the client says was never given"}, {"id": "r6", "text": "A student refers to a client by the diagnosis rather than by name during handover"}], "columns": [{"id": "c1", "text": "Intervene at once and take over the task"}, {"id": "c2", "text": "Speak to the person privately afterwards"}, {"id": "c3", "text": "Report to the supervisor"}], "row_label": "Observed behaviour"}'::jsonb,
 '{"cells": {"r1": "c1", "r2": "c3", "r3": "c2", "r4": "c1", "r5": "c3", "r6": "c2"}, "feedback": {}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Staff behaviour escalation', 'Choosing the level of response',
 'Very hard', 'CURATOR_LABEL', 'Evaluate', '{}', 'Select one column for each row.', 6, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530034', 'SATA', 'A registered nurse observes the practice of the team on a surgical ward. Which observations require the nurse to intervene immediately? Select all that apply.', 'Immediate intervention is reserved for practice that puts someone in danger now. Performing a sterile procedure without gloves, leaving a used needle loose on a bed and reaching across an open sterile field all create harm at the moment they happen. Correct use of gloves and an apron for drainage or a spillage is safe practice and needs no intervention at all.',
 '{"options": [{"id": "A", "text": "A colleague performs a sterile dressing change without applying gloves"}, {"id": "B", "text": "A healthcare assistant empties a urinary drainage bag wearing gloves and an apron"}, {"id": "C", "text": "A student places a used needle on the bed while looking for the sharps bin"}, {"id": "D", "text": "A nurse cleans a small blood spillage wearing gloves and a disposable apron"}, {"id": "E", "text": "A colleague reaches across an open sterile field to pass a dressing"}, {"id": "F", "text": "A nurse performs hand hygiene between two clients in the same bay"}]}'::jsonb,
 '{"answers": ["A", "C", "E"], "feedback": {"A": "Correct. A sterile procedure without gloves exposes the client to infection at that moment.", "B": "Incorrect. Gloves and an apron are the correct protection for handling drainage.", "C": "Correct. A loose used needle on a bed is a sharps injury waiting to happen.", "D": "Incorrect. This is the correct protection for dealing with a blood spillage.", "E": "Correct. Reaching across an open sterile field contaminates it immediately.", "F": "Incorrect. Hand hygiene between clients is exactly what should happen."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control',
 'Leadership and Management', 'Not applicable', 'Intervening in unsafe practice', 'Immediate danger',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530035', 'MCQ', 'A client with delirium is on continuous one-to-one observation because of a high risk of falling. The nurse carrying out the observation is called to help in another bay. The daughter of the client is visiting. Which action by the registered nurse is correct?', 'A safety responsibility is never handed to a relative or a visitor. One-to-one observation is a clinical intervention with agreed criteria for what is watched for and what is reported, and a visitor has neither the preparation nor the accountability for it. The observation is handed over to another member of staff before the first nurse leaves the bedside. Raising all four cot sides is a restraint and is not a substitute for supervision.',
 '{"options": [{"id": "A", "text": "Ask the daughter to sit with the client until the nurse returns"}, {"id": "B", "text": "Arrange for another member of staff to take over the observation before the nurse leaves"}, {"id": "C", "text": "Raise all four cot sides and ask the daughter to press the call bell if needed"}, {"id": "D", "text": "Move the client to a chair at the nurses station and ask the ward clerk to watch"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. A safety responsibility may not be delegated to a relative or visitor.", "B": "Correct. Continuous observation is handed over to a prepared member of staff without a gap.", "C": "Incorrect. Four raised cot sides constitute a restraint and increase the risk of injury from climbing.", "D": "Incorrect. The ward clerk is not prepared for the observation and has other duties."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control',
 'Leadership and Management', 'Not applicable', 'Delegating to family and visitors', 'One-to-one observation',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530036', 'SATA', 'A community nurse is preparing to teach the husband of a client with advanced dementia to use a bed rail safely at home. Which actions by the nurse are required? Select all that apply.', 'A family carer may take on a safety task only after being taught, only after demonstrating the task back, and only when the teaching and the demonstration have been documented. Written information and planned follow-up complete the handover. Asking a carer to sign away liability has no clinical or legal value, and the nurse does not stop being accountable for the adequacy of the teaching.',
 '{"options": [{"id": "A", "text": "Explain and demonstrate the correct use of the bed rail"}, {"id": "B", "text": "Ask the husband to demonstrate the task back before the nurse leaves"}, {"id": "C", "text": "Record the teaching and the return demonstration in the client notes"}, {"id": "D", "text": "Ask the husband to sign a form accepting responsibility for any injury"}, {"id": "E", "text": "Leave written instructions and arrange a follow-up visit"}, {"id": "F", "text": "Tell the husband that the nurse is no longer accountable once teaching has been given"}]}'::jsonb,
 '{"answers": ["A", "B", "C", "E"], "feedback": {"A": "Correct. Teaching a safety task begins with explanation and demonstration.", "B": "Correct. A return demonstration is the only evidence that the task has been understood.", "C": "Correct. Documented teaching is what makes the arrangement defensible and reviewable.", "D": "Incorrect. A waiver does not transfer accountability and has no clinical value.", "E": "Correct. Written information and follow-up support safe use over time.", "F": "Incorrect. The nurse remains accountable for the adequacy of the teaching and the follow-up."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Delegating to family and visitors', 'Teaching a family carer',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530037', 'MCQ', 'A client with heart failure has lost 4 kg in six weeks, leaves most of each meal and asks the nurse which foods are allowed on a low-salt diet. Which referral is most appropriate?', 'Referral follows the problem. Unintentional weight loss combined with a specific question about a therapeutic diet is a nutritional problem, and the dietitian is the member of the team who assesses intake, calculates requirements and translates a restriction into meals the client will actually eat. The other disciplines address mobility, function and social circumstances, none of which is the presenting problem here.',
 '{"options": [{"id": "A", "text": "Dietitian"}, {"id": "B", "text": "Physiotherapist"}, {"id": "C", "text": "Occupational therapist"}, {"id": "D", "text": "Social worker"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Weight loss with a question about a therapeutic diet is a nutritional referral.", "B": "Incorrect. Physiotherapy addresses mobility and exercise tolerance, not dietary intake.", "C": "Incorrect. Occupational therapy addresses function and activities of daily living.", "D": "Incorrect. A social work referral addresses finance, housing and support at home."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Care coordination', 'Referral to the dietitian',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SELN_530038', 'SELECT_N', 'A client is being prepared for discharge home two weeks after a stroke. The client walks short distances with a frame, cannot dress or wash without help, and takes a modified-consistency diet after a swallow assessment. Which 3 referrals should the nurse arrange?', 'Each referral answers one identified problem. Walking with a frame is a physiotherapy problem, difficulty with dressing and washing is an occupational therapy problem, and a modified-consistency diet requires the speech and language therapist to review the swallow before and after discharge. Referrals that answer no stated problem waste the time of the client and the service.',
 '{"options": [{"id": "A", "text": "Physiotherapist"}, {"id": "B", "text": "Occupational therapist"}, {"id": "C", "text": "Speech and language therapist"}, {"id": "D", "text": "Chaplain"}, {"id": "E", "text": "Interpreter service"}, {"id": "F", "text": "Podiatrist"}], "select_count": 3}'::jsonb,
 '{"answers": ["A", "B", "C"], "feedback": {"A": "Correct. Mobility with a walking aid is assessed and progressed by physiotherapy.", "B": "Correct. Difficulty with dressing and washing is an occupational therapy assessment.", "C": "Correct. A modified-consistency diet requires ongoing review of the swallow.", "D": "Incorrect. No spiritual need has been identified in this client.", "E": "Incorrect. Nothing in the scenario indicates a language barrier.", "F": "Incorrect. No foot or nail problem has been described."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem', 'Care coordination', 'Discharge referrals after a stroke',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530039', 'SATA', 'A client who speaks limited English is admitted for a hysterectomy. Which actions by the nurse are appropriate? Select all that apply.', 'Consent and clinical information require a professional interpreter, whether face to face or by telephone. Family members, and particularly children, must not be used: they may edit distressing information, they cannot be held to a standard of accuracy, and their presence destroys the confidentiality of the discussion. The use of an interpreter and the method used are recorded, because that record is part of the evidence that consent was informed.',
 '{"options": [{"id": "A", "text": "Arrange a professional interpreter for the consent discussion"}, {"id": "B", "text": "Ask the 15-year-old son of the client to translate the consent discussion"}, {"id": "C", "text": "Record in the notes that an interpreter was used and by what method"}, {"id": "D", "text": "Speak clearly, facing the client, and allow time for questions"}, {"id": "E", "text": "Ask a cleaner who speaks the same language to interpret the surgical explanation"}, {"id": "F", "text": "Use the telephone interpreting service when a face-to-face interpreter is unavailable"}]}'::jsonb,
 '{"answers": ["A", "C", "D", "F"], "feedback": {"A": "Correct. Consent discussions require a professional interpreter.", "B": "Incorrect. A child must never interpret; accuracy and confidentiality are both lost.", "C": "Correct. Recording the interpreter and the method supports the validity of the consent.", "D": "Correct. Clear speech and time for questions support understanding alongside interpretation.", "E": "Incorrect. An untrained staff member is not a professional interpreter and breaches confidentiality.", "F": "Correct. Telephone interpreting is an accepted alternative when no interpreter can attend."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Care coordination', 'Interpreter services',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_TF_530040', 'TF', 'Discharge planning for a client admitted to a medical ward should begin at the time of admission. True or false?', 'Discharge planning starts at admission because the things that delay a discharge - equipment, a package of care, housing, transport, teaching a new medication - all take days to arrange. Waiting until the client is medically fit compresses that work into a single afternoon and produces avoidable readmissions. The plan is then revised as the condition and the social picture change.',
 '{"options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Planning from admission allows equipment, support and teaching to be arranged in time.", "B": "Incorrect. Leaving planning until the client is medically fit delays discharge and raises readmission risk."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Care coordination', 'Discharge planning',
 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MMR_530041', 'MATRIX_MR', 'A nurse is arranging referrals for four clients on a medical ward. For each situation, select every member of the wider team who should be involved.', 'Care coordination means matching each identified need to the discipline that owns it, and accepting that one client may generate several referrals at once. Nutrition problems go to the dietitian, money, housing and support at home to the social worker, and spiritual or religious need to the chaplaincy service. A client with two problems needs two referrals, not the one that is easiest to arrange.',
 '{"rows": [{"id": "r1", "text": "A client with newly diagnosed coeliac disease who does not know which foods to avoid"}, {"id": "r2", "text": "A client who cannot afford the new inhalers and has no fixed address"}, {"id": "r3", "text": "A client with a terminal diagnosis who asks to speak to someone about his faith"}, {"id": "r4", "text": "A client with a new stoma who is losing weight and has no one at home to help with the appliance"}, {"id": "r5", "text": "A client receiving palliative care whose family cannot afford the funeral and who wishes for prayers at the bedside"}], "columns": [{"id": "c1", "text": "Dietitian"}, {"id": "c2", "text": "Social worker"}, {"id": "c3", "text": "Chaplaincy service"}], "row_label": "Client situation"}'::jsonb,
 '{"cells": {"r1": ["c1"], "r2": ["c2"], "r3": ["c3"], "r4": ["c1", "c2"], "r5": ["c2", "c3"]}, "feedback": {}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Care coordination', 'Matching need to discipline',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 'Select all that apply for each row.', 7, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530042', 'MCQ', 'A nurse is telephoning the provider about a client whose urine output has fallen to 15 mL per hour. Using the SBAR tool, which statement belongs in the recommendation?', 'SBAR ends with a recommendation because a report without one leaves the provider to guess what the nurse wants. The recommendation states what the nurse is asking for and by when, and often includes a specific request such as permission for a fluid challenge. Identifying the caller and the client is the situation, the surgical history is the background, and the current figures are the assessment.',
 '{"options": [{"id": "A", "text": "\"This is the nurse on Ward 4 calling about the client in bed 12.\""}, {"id": "B", "text": "\"He had a bowel resection two days ago and has an epidural infusion running.\""}, {"id": "C", "text": "\"His blood pressure is 96/54 mmHg and he has passed 45 mL in the last three hours.\""}, {"id": "D", "text": "\"Would you review him within the next 30 minutes, and may I give a 250 mL fluid challenge meanwhile?\""}]}'::jsonb,
 '{"answer": "D", "feedback": {"A": "Incorrect. Identifying the caller and the client is the situation.", "B": "Incorrect. The surgical history and current infusions are the background.", "C": "Incorrect. The current findings are the assessment.", "D": "Correct. A specific request with a timeframe is the recommendation."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Interdisciplinary communication', 'SBAR',
 'Easy', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530043', 'SATA', 'A nurse is giving a bedside handover to the oncoming shift. Which items should be included? Select all that apply.', 'A handover transfers responsibility, so it carries what the next nurse must act on: the current condition, what has changed, what is outstanding and when it is due, the plan up to the next handover, and any result still awaited with the name of the person chasing it. Personal opinions about a family and information about other clients belong nowhere in a handover, and at the bedside they also breach confidentiality.',
 '{"options": [{"id": "A", "text": "The current condition of the client and any change during the shift"}, {"id": "B", "text": "Outstanding tasks and the time each is due"}, {"id": "C", "text": "A personal opinion about how demanding the family have been"}, {"id": "D", "text": "The plan of care and what is expected before the next handover"}, {"id": "E", "text": "A discussion of the diagnosis of the client in the next bed"}, {"id": "F", "text": "Any result still awaited and who is following it up"}]}'::jsonb,
 '{"answers": ["A", "B", "D", "F"], "feedback": {"A": "Correct. The current condition and any change are the core of a handover.", "B": "Correct. Outstanding tasks with times prevent omissions across the shift boundary.", "C": "Incorrect. A personal judgement about the family is neither factual nor useful.", "D": "Correct. Stating the plan sets expectations for the coming shift.", "E": "Incorrect. Discussing another client at this bedside breaches confidentiality.", "F": "Correct. Naming who is chasing an outstanding result prevents it being lost."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Interdisciplinary communication', 'Handover content',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530044', 'MCQ', 'A nurse telephones the provider about a client whose respiratory rate has risen to 28 breaths per minute with a falling oxygen saturation. The provider replies that the client is simply anxious and ends the call. Over the next 20 minutes the client looks worse. Which action should the nurse take FIRST?', 'FIRST asks what comes next in sequence. Before the concern can be escalated it has to be restated with current data, and the client may in any case now need immediate treatment such as more oxygen or repositioning. Escalating with figures that are 20 minutes old weakens the case and delays the assessment the client needs now.',
 '{"options": [{"id": "A", "text": "Reassess the client and record a full set of current observations"}, {"id": "B", "text": "Telephone the nursing supervisor about the response of the provider"}, {"id": "C", "text": "Complete an incident report describing the refusal to attend"}, {"id": "D", "text": "Ask a colleague to give a second opinion on the client"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Current objective data is needed both to treat the client now and to escalate credibly.", "B": "Incorrect. Escalation is right but should carry current findings rather than 20-minute-old ones.", "C": "Incorrect. An incident report documents the event afterwards; it does not help the client now.", "D": "Incorrect. A colleague opinion delays the nursing assessment the client needs."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem', 'Interdisciplinary communication', 'Escalating a dismissed concern',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530045', 'MCQ', 'The nurse has reassessed the client. The respiratory rate is now 32 breaths per minute, the oxygen saturation is 88% on 4 litres of oxygen per minute and the client is using accessory muscles. The provider has already dismissed the concern once. Which action is the PRIORITY?', 'PRIORITY asks what matters most, and what matters most is that this client is seen urgently by someone who can treat him. The chain of command exists precisely for the situation in which the first clinician contacted does not respond adequately: the nurse moves up to the nursing supervisor and requests urgent medical review. Documenting that the provider was informed protects nobody, least of all the client.',
 '{"options": [{"id": "A", "text": "Escalate through the chain of command to the nursing supervisor and request urgent medical review"}, {"id": "B", "text": "Telephone the same provider again and repeat the SBAR report"}, {"id": "C", "text": "Wait for the scheduled ward round, which is due in one hour"}, {"id": "D", "text": "Document that the provider was informed and declined to attend"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Deterioration after a dismissed concern is exactly what the chain of command is for.", "B": "Incorrect. The same provider has already declined once and the client is now deteriorating.", "C": "Incorrect. An hour is far too long for a client with worsening respiratory failure.", "D": "Incorrect. Documentation alone leaves an untreated client and does not discharge the duty of care."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem', 'Interdisciplinary communication', 'Chain of command',
 'Very hard', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530046', 'SATA', 'A nurse manager is reviewing which events on the unit require an incident report. Which events should be reported? Select all that apply.', 'Incident reporting covers harm, near misses and equipment failure, and it includes visitors as well as clients. A near miss is reported precisely because no one was hurt: it shows where the system nearly failed while there is still time to change it. A documented refusal of medication and a routine discharge are normal care and generate no report.',
 '{"options": [{"id": "A", "text": "A wrong dose was drawn up but was noticed and discarded before it reached the client"}, {"id": "B", "text": "A client fell while walking to the bathroom"}, {"id": "C", "text": "A visitor slipped on a wet floor in the corridor"}, {"id": "D", "text": "A client refused a prescribed medication and the refusal was documented"}, {"id": "E", "text": "An infusion pump stopped working during a transfusion"}, {"id": "F", "text": "A client was discharged home with a prescription and a follow-up appointment"}]}'::jsonb,
 '{"answers": ["A", "B", "C", "E"], "feedback": {"A": "Correct. A near miss is reported so that the system weakness can be corrected.", "B": "Correct. A client fall is an incident whether or not injury resulted.", "C": "Correct. Incidents involving visitors on the premises are reported.", "D": "Incorrect. A documented refusal is a client right exercised, not an incident.", "E": "Correct. Equipment failure is reported and the device is removed from use.", "F": "Incorrect. A planned discharge with follow-up is routine care."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Incident reporting', 'Near misses and just culture',
 'Medium', 'CURATOR_LABEL', 'Understand', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530047', 'MCQ', 'After a client received the medication intended for another client, the unit carries out a root cause analysis. Which statement best describes the purpose?', 'A root cause analysis asks why the system allowed the error rather than who made it. It traces the sequence backwards - look-alike names, an interrupted checking process, a chart at the wrong bedside - and changes the conditions that made the error possible. In a just culture, honest error is examined for its causes while reckless behaviour is still addressed individually.',
 '{"options": [{"id": "A", "text": "To identify the system failures that allowed the error and to change them"}, {"id": "B", "text": "To decide which nurse was responsible so that the record can be corrected"}, {"id": "C", "text": "To satisfy the requirement that an incident report is completed"}, {"id": "D", "text": "To determine whether the client is likely to take legal action"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. A root cause analysis examines the system so that the same error cannot recur.", "B": "Incorrect. Attributing individual blame is what a just culture deliberately avoids.", "C": "Incorrect. The incident report is a separate document and is not the purpose of the analysis.", "D": "Incorrect. Legal exposure is not the purpose of a clinical safety review."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Incident reporting', 'Root cause analysis',
 'Hard', 'CURATOR_LABEL', 'Understand', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530048', 'SATA', 'A client is due to have a laparoscopic cholecystectomy this afternoon. Which responsibilities belong to the nurse in relation to the consent form? Select all that apply.', 'Informed consent is obtained by the clinician who will perform the procedure, because only that person can explain the technique, the alternatives and the risks. The nurse confirms that the signature is voluntary, witnesses it, checks that the client can describe in his own words what is planned, and reports any uncertainty back to the provider before the client leaves the ward.',
 '{"options": [{"id": "A", "text": "Confirming that the client has signed the form voluntarily"}, {"id": "B", "text": "Explaining the surgical technique, the alternatives and the risks"}, {"id": "C", "text": "Witnessing the signature of the client"}, {"id": "D", "text": "Checking that the client can describe what is going to be done"}, {"id": "E", "text": "Deciding whether the client has the capacity to consent"}, {"id": "F", "text": "Informing the provider if the client expresses uncertainty"}]}'::jsonb,
 '{"answers": ["A", "C", "D", "F"], "feedback": {"A": "Correct. The nurse confirms that consent has been given freely and without pressure.", "B": "Incorrect. The explanation is given by the clinician performing the procedure.", "C": "Correct. Witnessing the signature is a recognised nursing responsibility.", "D": "Correct. Checking understanding is how the nurse detects that consent is not informed.", "E": "Incorrect. The determination of capacity rests with the clinician obtaining the consent.", "F": "Correct. Uncertainty is reported to the provider before the client goes to theatre."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Informed consent', 'Role of the nurse',
 'Medium', 'CURATOR_LABEL', 'Understand', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530049', 'MCQ', 'While preparing a client for theatre the nurse asks what operation is planned. The client replies, "They are taking something out of my stomach, but I am not really sure what." The consent form is already signed. Which action should the nurse take?', 'A signature is not consent; understanding is. When a client cannot describe what is planned, the consent is not informed and the provider who obtained it must return and explain again before the client leaves the ward. The nurse does not fill the gap personally, because the duty to explain the procedure, the alternatives and the risks sits with the clinician performing it.',
 '{"options": [{"id": "A", "text": "Contact the provider to speak with the client before the client goes to theatre"}, {"id": "B", "text": "Explain the operation to the client using the theatre list as a guide"}, {"id": "C", "text": "Reassure the client that the surgeon will explain in the anaesthetic room"}, {"id": "D", "text": "Ask the client to sign a second consent form once someone has explained"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Consent is not informed, so the clinician who obtained it must explain again.", "B": "Incorrect. Explaining the procedure is the responsibility of the clinician performing it.", "C": "Incorrect. The anaesthetic room is too late, and the client is then under pressure to proceed.", "D": "Incorrect. A second signature adds nothing while the client still does not understand."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Informed consent', 'Consent that is not informed',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530050', 'MCQ', 'A client who has an advance directive declining cardiopulmonary resuscitation tells the nurse, "I have changed my mind. If my heart stops I want everything done." Which action by the nurse is correct?', 'An advance directive expresses the current wishes of the client, and a client with capacity may revise or revoke it at any time, verbally as well as in writing. The nurse informs the provider and the team immediately and ensures the record and the resuscitation status are updated, because until that happens the team may act on a document the client has withdrawn. The views of the family do not override the wishes of the client.',
 '{"options": [{"id": "A", "text": "Explain that the directive was signed and cannot be altered during this admission"}, {"id": "B", "text": "Inform the provider and the team at once and ensure the record is updated"}, {"id": "C", "text": "Ask the family whether they agree with the change before recording it"}, {"id": "D", "text": "Explain that the change cannot take effect until it is put in writing"}]}'::jsonb,
 '{"answer": "B", "feedback": {"A": "Incorrect. A client with capacity may revoke an advance directive at any time.", "B": "Correct. The team is informed immediately and the record and resuscitation status updated.", "C": "Incorrect. The wishes of a client with capacity are not subject to family agreement.", "D": "Incorrect. A verbal revocation by a client with capacity is effective at once."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Client rights', 'Advance directives',
 'Easy', 'CURATOR_LABEL', 'Apply', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  instruction, marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_SATA_530051', 'SATA', 'Which actions by a nurse protect the confidentiality of client information? Select all that apply.', 'Information is shared on the basis of need to know for the care of that client, and with the consent of the client where the request comes from outside the team. That allows disclosure to a physiotherapist treating the client but not to a relative simply because he is next of kin, and it forbids looking up a record out of personal concern. Conversations in lifts and corridors are overheard far more often than staff imagine.',
 '{"options": [{"id": "A", "text": "Confirming the identity of a telephone caller and the consent of the client before giving information"}, {"id": "B", "text": "Discussing the results of a client with a colleague in the lift"}, {"id": "C", "text": "Logging out of the electronic record before leaving the computer"}, {"id": "D", "text": "Sharing relevant information with the physiotherapist who is treating the client"}, {"id": "E", "text": "Looking up the record of a neighbour admitted to another ward out of concern"}, {"id": "F", "text": "Telling a relative the diagnosis because the relative is the next of kin"}]}'::jsonb,
 '{"answers": ["A", "C", "D"], "feedback": {"A": "Correct. Identity and client consent are both verified before information is released by telephone.", "B": "Incorrect. Clinical conversations in public areas are routinely overheard.", "C": "Correct. An open record on an unattended screen is an unrestricted disclosure.", "D": "Correct. Sharing with a clinician treating the client is disclosure on a need-to-know basis.", "E": "Incorrect. Concern for a neighbour is not a care relationship and this is a breach.", "F": "Incorrect. Next of kin status alone does not entitle a relative to clinical information."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Client rights', 'Confidentiality and disclosure',
 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 'Select all that apply.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530052', 'MCQ', 'A client with a haemoglobin of 6.8 g/dL who is alert and fully orientated refuses the prescribed blood transfusion. Which action should the nurse take FIRST?', 'FIRST asks what comes next in sequence, and the sequence begins with finding out why. A refusal often rests on a fear, a misunderstanding about the risk of infection, or a religious position the team needs to know about, and some of those can be answered on the spot. Notifying the provider, teaching about the risks and documenting the refusal all follow, but none of them can be done well without knowing the reason.',
 '{"options": [{"id": "A", "text": "Ask the client what concerns lie behind the decision"}, {"id": "B", "text": "Notify the provider that the client has refused the transfusion"}, {"id": "C", "text": "Document the refusal in the clinical record"}, {"id": "D", "text": "Explain the risks of leaving severe anaemia untreated"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. Exploring the reason comes first and may resolve a correctable misunderstanding.", "B": "Incorrect. The provider is informed, but not before the nurse understands the reason.", "C": "Incorrect. Documentation records the outcome of the conversation that has not yet happened.", "D": "Incorrect. Information given before the concern is understood rarely addresses it."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem', 'Client rights', 'Refusal of treatment',
 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_530053', 'MCQ', 'A client who is alert and fully orientated has listened to a full explanation from the provider and continues to refuse a prescribed blood transfusion. Which action is the PRIORITY for the nurse?', 'PRIORITY asks what matters most, and what matters most is the right of a client with capacity to refuse treatment even when the refusal carries serious risk. The nurse upholds the decision, ensures the provider knows, and documents both the refusal and the explanation that was given. Recruiting the family, questioning capacity because of the decision itself, or hoping the client will weaken are all coercive.',
 '{"options": [{"id": "A", "text": "Uphold the decision, inform the provider and document the refusal and the discussion"}, {"id": "B", "text": "Ask the family to persuade the client to accept the transfusion"}, {"id": "C", "text": "Arrange a psychiatric assessment because the refusal puts the client at risk"}, {"id": "D", "text": "Delay the decision and approach the client again when the haemoglobin falls further"}]}'::jsonb,
 '{"answer": "A", "feedback": {"A": "Correct. A client with capacity may refuse treatment, and the refusal is upheld and documented.", "B": "Incorrect. Using the family to apply pressure undermines a valid refusal.", "C": "Incorrect. An unwelcome decision is not in itself evidence of impaired capacity.", "D": "Incorrect. Waiting for the client to become weaker in order to re-ask is coercive."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Multisystem', 'Client rights', 'Refusal of treatment',
 'Very hard', 'CURATOR_LABEL', 'Evaluate', '{}', NULL, 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SELN_530054', 'SELECT_N', 'A charge nurse on an adult medical ward is allocating clients to a nurse who has been floated from the paediatric unit for one shift. Which 3 clients are appropriate to assign?', 'A float nurse is a competent nurse in an unfamiliar setting, so the assignment is matched to what transfers rather than to the number of clients. Stable clients on established treatment, and clients awaiting discharge, draw on skills any registered nurse holds. Clients with a new chest drain, a titrated insulin infusion or a fresh arterial puncture site need judgement specific to adult acute care.',
 '{"options": [{"id": "A", "text": "A client with cellulitis receiving intravenous antibiotics whose condition is otherwise stable"}, {"id": "B", "text": "A client awaiting discharge after treatment for a urinary tract infection"}, {"id": "C", "text": "A client with well-controlled type 2 diabetes admitted while home care is arranged"}, {"id": "D", "text": "A client whose chest drain was inserted two hours ago"}, {"id": "E", "text": "A client receiving a continuous insulin infusion for diabetic ketoacidosis"}, {"id": "F", "text": "A client who returned from a coronary angiogram 30 minutes ago"}], "select_count": 3}'::jsonb,
 '{"answers": ["A", "B", "C"], "feedback": {"A": "Correct. Established intravenous antibiotic therapy in a stable client is within general competence.", "B": "Correct. A client awaiting discharge has a predictable and stable course.", "C": "Correct. A stable client admitted for social reasons requires no specialist adult acute skills.", "D": "Incorrect. A new chest drain requires specific assessment and troubleshooting skills.", "E": "Incorrect. A titrated insulin infusion requires frequent adjustment against a protocol.", "F": "Incorrect. The period after an angiogram requires monitoring of the puncture site and limb perfusion."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Assignment decisions', 'The float nurse',
 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 'Select 3.', 3, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_530055', 'SATA', 'A nurse is told to take charge of a haemodialysis unit for one shift and has never worked in dialysis. Which actions by the nurse are appropriate? Select all that apply.', 'A nurse may not accept responsibility for care that is beyond demonstrated competence, but neither may a nurse simply walk away from clients already accepted, which is abandonment. The safe route is to state precisely what is and is not within competence, negotiate an assignment that matches it, offer the tasks that do transfer, and document the discussion and its outcome.',
 '{"options": [{"id": "A", "text": "State clearly which tasks are and are not within the competence of the nurse"}, {"id": "B", "text": "Refuse the assignment and leave the unit at the start of the shift"}, {"id": "C", "text": "Ask the nurse manager for an assignment that matches the competence of the nurse"}, {"id": "D", "text": "Accept the assignment and learn to operate the machines from the healthcare assistant"}, {"id": "E", "text": "Document the discussion with the manager and the outcome"}, {"id": "F", "text": "Offer to carry out tasks that are within competence, such as observations and medication administration, with support"}]}'::jsonb,
 '{"answers": ["A", "C", "E", "F"], "feedback": {"A": "Correct. A specific statement of competence is more useful than a blanket refusal.", "B": "Incorrect. Leaving clients who have been accepted constitutes abandonment.", "C": "Correct. Negotiating an assignment that matches competence protects clients and the nurse.", "D": "Incorrect. Learning a specialist skill informally, from someone who does not hold it, is unsafe.", "E": "Correct. A documented record of the discussion protects the client and the nurse.", "F": "Correct. Contributing the skills that do transfer keeps the unit staffed safely."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care',
 'Leadership and Management', 'Not applicable', 'Assignment decisions', 'Accepting or declining an assignment',
 'Very hard', 'CURATOR_LABEL', 'Evaluate', '{}', 'Select all that apply.', 4, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');
